svg.script:
    var eventDataIndex = {};
    var tooltipTimer = null;
var laneColorIndex = {};
function registerEventData(eventId, data) {
  eventDataIndex[eventId] = data;
}
function registerLaneColor(laneId, fillColor, strokeColor, textColor) {
  laneColorIndex[laneId] = { fillColor, strokeColor, textColor };
}
function showTooltip(evt, eventId) {
  if (tooltipTimer) {
    clearTimeout(tooltipTimer);
  }
  tooltipTimer = setTimeout(function() {
    var tooltip = document.getElementById("tooltip");
    if (!tooltip) {
      tooltip = document.createElementNS("http://www.w3.org/2000/svg", "g");
      tooltip.setAttribute("id", "tooltip");
      var rect = document.createElementNS("http://www.w3.org/2000/svg", "rect");
      rect.setAttribute("rx", "5");
      rect.setAttribute("fill", "#333");
      rect.setAttribute("stroke", "#000");
      rect.setAttribute("stroke-width", "1");
      tooltip.appendChild(rect);
      document.querySelector("svg").appendChild(tooltip);
    }
    var data = eventDataIndex[eventId];
    if (data) {
    var svg = document.querySelector("svg");
    var svgRect = svg.getBoundingClientRect();
    var maxWidth = Math.min(400, svgRect.width - 50);
    var x = evt.clientX - svgRect.left + 15;
    var y = evt.clientY - svgRect.top - 10;
    if (x + maxWidth > svgRect.width) {
      x = svgRect.width - maxWidth - 10;
    }
    tooltip.setAttribute("transform", "translate(" + x + "," + y + ")");
    while (tooltip.querySelector("text")) {
      tooltip.removeChild(tooltip.querySelector("text"));
    }
    var lines = [];
    if (data.phase) lines.push("Phase: " + data.phase);
    if (data.actor) lines.push("Actor: " + data.actor);
    if (data.summary) lines.push("Summary: " + data.summary);
    var wrappedLines = [];
    var charWidth = 7;
    var maxCharsPerLine = Math.floor(maxWidth / charWidth) - 2;
    for (var i = 0; i < lines.length; i++) {
      var line = lines[i];
      var maxIter = 50;
      var iter = 0;
      while (line.length > maxCharsPerLine && iter < maxIter) {
        var splitIndex = line.lastIndexOf(" ", maxCharsPerLine);
        if (splitIndex <= 3) splitIndex = maxCharsPerLine;
        wrappedLines.push(line.substring(0, splitIndex));
        var remaining = line.substring(splitIndex).trim();
        line = remaining ? "  " + remaining : "";
        iter++;
      }
      if (line) wrappedLines.push(line);
    }
    var lineHeight = 18;
    var text = document.createElementNS("http://www.w3.org/2000/svg", "text");
    text.setAttribute("fill", "#fff");
    text.setAttribute("font-size", "12");
    text.setAttribute("font-family", "Arial");
    text.setAttribute("x", "10");
    text.setAttribute("y", "20");
    for (var i = 0; i < wrappedLines.length; i++) {
      var tspan = document.createElementNS("http://www.w3.org/2000/svg", "tspan");
      tspan.setAttribute("x", "10");
      tspan.setAttribute("dy", i === 0 ? "0" : lineHeight);
      tspan.textContent = wrappedLines[i];
      text.appendChild(tspan);
    }
    tooltip.appendChild(text);
    var bbox = text.getBBox();
    var tooltipWidth = Math.min(bbox.width + 20, maxWidth + 20);
    tooltip.querySelector("rect").setAttribute("width", tooltipWidth);
    tooltip.querySelector("rect").setAttribute("height", wrappedLines.length * lineHeight + 5);
    tooltip.setAttribute("visibility", "visible");
    }
  }, 1000);
}
function hideTooltip() {
  if (tooltipTimer) {
    clearTimeout(tooltipTimer);
    tooltipTimer = null;
  }
  var tooltip = document.getElementById("tooltip");
  if (tooltip) {
    tooltip.setAttribute("visibility", "hidden");
  }
}
function scrollToElement(elementId) {
  var data = eventDataIndex[elementId];
  if (data) {
    var svgElement = document.querySelector("svg");
    if (svgElement) {
      var svgRect = svgElement.getBoundingClientRect();
      var scaleX = svgRect.width / svgElement.getAttribute("width");
      var scaleY = svgRect.height / svgElement.getAttribute("height");
      var elementLeft = svgRect.left + data.x * scaleX;
      var elementTop = svgRect.top + data.y * scaleY;
      var scrollX = elementLeft + window.scrollX - window.innerWidth / 2 + data.width * scaleX / 2;
      var scrollY = elementTop + window.scrollY - window.innerHeight / 2 + data.height * scaleY / 2;
      window.scrollTo({ left: scrollX, top: scrollY, behavior: "smooth" });
    }
  }
}
var currentDetailPanel = null;
function showDetailPanel(evt, eventId) {
  console.log("showDetailPanel called with eventId:", eventId);
  hideTooltip();
  if (evt && evt.stopPropagation) {
    evt.stopPropagation();
  }
  var data = eventDataIndex[eventId];
  if (!data) {
    console.log("No data found for eventId:", eventId);
    return;
  }
  console.log("Event data:", data);
  var svg = document.querySelector("svg");
  if (!svg) {
    console.log("SVG element not found");
    return;
  }
  var svgRect = svg.getBoundingClientRect();
  var scaleX = svgRect.width / svg.getAttribute("width");
  var elementCenterX = svgRect.left + data.x * scaleX + data.width * scaleX / 2;
  var scrollX = elementCenterX + window.scrollX - window.innerWidth / 2;
  window.scrollTo({ left: scrollX, top: window.scrollY, behavior: "smooth" });
  setTimeout(function() {
    console.log("SVG rect:", svgRect);
    var detailPanel = document.getElementById("detailPanel");
    if (!detailPanel) {
      detailPanel = document.createElementNS("http://www.w3.org/2000/svg", "g");
      detailPanel.setAttribute("id", "detailPanel");
      var rect = document.createElementNS("http://www.w3.org/2000/svg", "rect");
      rect.setAttribute("rx", "8");
      rect.setAttribute("fill", "#fff");
      rect.setAttribute("stroke", "#333");
      rect.setAttribute("stroke-width", "2");
      detailPanel.appendChild(rect);
      var closeBtn = document.createElementNS("http://www.w3.org/2000/svg", "g");
      closeBtn.setAttribute("id", "detailPanelCloseBtn");
      closeBtn.setAttribute("style", "cursor: pointer;");
      closeBtn.setAttribute("pointer-events", "auto");
      closeBtn.setAttribute("onclick", "event.stopPropagation(); closeDetailPanel();");
      detailPanel.appendChild(closeBtn);
      svg.appendChild(detailPanel);
      console.log("Created new detail panel");
    }
    svgRect = svg.getBoundingClientRect();
    var maxWidth = Math.min(600, window.innerWidth - 60);
    var panelX = window.innerWidth / 2 - maxWidth / 2 - svgRect.left;
    var panelY = window.innerHeight / 2 - 120 - svgRect.top;
    if (panelX < 10) panelX = 10;
    if (panelY < 10) panelY = 10;
    console.log("Panel position:", panelX, panelY);
    detailPanel.setAttribute("transform", "translate(" + panelX + "," + panelY + ")");
  while (detailPanel.querySelector("text")) {
    detailPanel.removeChild(detailPanel.querySelector("text"));
  }
  var fields = [];
  if (data.ts) fields.push({name: "Timestamp", value: data.ts});
  if (data.systemId) fields.push({name: "SystemId", value: data.systemId});
  if (data.tracerId) fields.push({name: "TracerId", value: data.tracerId});
  if (data.id) fields.push({name: "ID", value: data.id});
  if (data.phase) fields.push({name: "Phase", value: data.phase});
  if (data.actor) fields.push({name: "Actor", value: data.actor});
  if (data.action) fields.push({name: "Action", value: data.action});
  if (data.summary) fields.push({name: "Summary", value: data.summary});
  if (data.duration !== undefined) fields.push({name: "Duration", value: data.duration + "ms"});
  var wrappedFields = [];
  var charWidth = 7;
  var maxCharsPerLine = Math.floor(maxWidth / charWidth) - 4;
  for (var i = 0; i < fields.length; i++) {
    var field = fields[i];
    var value = field.value;
    var wrappedValues = [];
    var maxIter = 50;
    var iter = 0;
    while (value.length > maxCharsPerLine && iter < maxIter) {
      var splitIndex = value.lastIndexOf(" ", maxCharsPerLine);
      if (splitIndex <= 3) splitIndex = maxCharsPerLine;
      wrappedValues.push(value.substring(0, splitIndex));
      var remaining = value.substring(splitIndex).trim();
      value = remaining ? "  " + remaining : "";
      iter++;
    }
    if (value) wrappedValues.push(value);
    wrappedFields.push({name: field.name, values: wrappedValues});
  }
  var labelHeight = 18;
  var valueHeight = 16;
  var text = document.createElementNS("http://www.w3.org/2000/svg", "text");
  text.setAttribute("fill", textColor);
  text.setAttribute("font-size", "13");
  text.setAttribute("font-family", "Arial");
  text.setAttribute("x", "15");
  text.setAttribute("y", "25");
  var currentY = 25;
  for (var i = 0; i < wrappedFields.length; i++) {
    var wrappedField = wrappedFields[i];
    var nameTspan = document.createElementNS("http://www.w3.org/2000/svg", "tspan");
    nameTspan.setAttribute("x", "15");
    nameTspan.setAttribute("dy", i === 0 ? "0" : labelHeight);
    nameTspan.setAttribute("font-weight", "bold");
    nameTspan.textContent = wrappedField.name + ":";
    text.appendChild(nameTspan);
    for (var j = 0; j < wrappedField.values.length; j++) {
      var valueTspan = document.createElementNS("http://www.w3.org/2000/svg", "tspan");
      valueTspan.setAttribute("x", "15");
      valueTspan.setAttribute("dy", valueHeight);
      valueTspan.setAttribute("font-weight", "normal");
      valueTspan.textContent = wrappedField.values[j];
      text.appendChild(valueTspan);
    }
  }
  detailPanel.appendChild(text);
  var bbox = text.getBBox();
  var panelWidth = Math.min(bbox.width + 30, maxWidth + 30);
  var panelHeight = bbox.height + 30;
  detailPanel.querySelector("rect").setAttribute("width", panelWidth);
  detailPanel.querySelector("rect").setAttribute("height", panelHeight);
  var fillColor = "#fff";
  var strokeColor = "#333";
  var textColor = "#333";
  if (data.tracerId && laneColorIndex[data.tracerId]) {
    fillColor = laneColorIndex[data.tracerId].fillColor;
    strokeColor = laneColorIndex[data.tracerId].strokeColor;
    textColor = laneColorIndex[data.tracerId].textColor;
  } else if (data.fillColor) {
    fillColor = data.fillColor;
    strokeColor = data.strokeColor;
    textColor = data.textColor;
  }
  detailPanel.querySelector("rect").setAttribute("fill", fillColor);
  detailPanel.querySelector("rect").setAttribute("stroke", strokeColor);
  detailPanel.querySelector("rect").setAttribute("stroke-width", "2");
  var closeBtn = detailPanel.querySelector("#detailPanelCloseBtn");
  while (closeBtn.firstChild) {
    closeBtn.removeChild(closeBtn.firstChild);
  }
  var btnSize = 24;
  var btnX = panelWidth - btnSize - 10;
  var btnY = 10;
  var btnRect = document.createElementNS("http://www.w3.org/2000/svg", "rect");
  btnRect.setAttribute("x", btnX);
  btnRect.setAttribute("y", btnY);
  btnRect.setAttribute("width", btnSize);
  btnRect.setAttribute("height", btnSize);
  btnRect.setAttribute("rx", btnSize / 2);
  btnRect.setAttribute("fill", strokeColor);
  btnRect.setAttribute("style", "cursor: pointer;");
  btnRect.setAttribute("pointer-events", "auto");
  closeBtn.appendChild(btnRect);
  var xGroup = document.createElementNS("http://www.w3.org/2000/svg", "g");
  xGroup.setAttribute("pointer-events", "auto");
  var xLine1 = document.createElementNS("http://www.w3.org/2000/svg", "line");
  xLine1.setAttribute("x1", btnX + 6);
  xLine1.setAttribute("y1", btnY + 6);
  xLine1.setAttribute("x2", btnX + btnSize - 6);
  xLine1.setAttribute("y2", btnY + btnSize - 6);
  xLine1.setAttribute("stroke", "#fff");
  xLine1.setAttribute("stroke-width", "2");
  xLine1.setAttribute("pointer-events", "auto");
  xGroup.appendChild(xLine1);
  var xLine2 = document.createElementNS("http://www.w3.org/2000/svg", "line");
  xLine2.setAttribute("x1", btnX + btnSize - 6);
  xLine2.setAttribute("y1", btnY + 6);
  xLine2.setAttribute("x2", btnX + 6);
  xLine2.setAttribute("y2", btnY + btnSize - 6);
  xLine2.setAttribute("stroke", "#fff");
  xLine2.setAttribute("stroke-width", "2");
  xLine2.setAttribute("pointer-events", "auto");
  xGroup.appendChild(xLine2);
  closeBtn.appendChild(xGroup);
  closeBtn.setAttribute("transform", "translate(0, 0)");
  closeBtn.setAttribute("onclick", "event.stopPropagation(); closeDetailPanel();");
  detailPanel.setAttribute("visibility", "visible");
  console.log("Detail panel shown");
  currentDetailPanel = detailPanel;
  svg.addEventListener("click", closeDetailPanelOnOutsideClick, true);
  }, 500);
}
function closeDetailPanelOnOutsideClick(evt) {
  if (evt && evt.stopPropagation) {
    evt.stopPropagation();
  }
  var target = evt.target;
  var detailPanel = document.getElementById("detailPanel");
  var closeBtn = document.getElementById("detailPanelCloseBtn");
  var isClickOnCloseBtn = false;
  var tempTarget = target;
  while (tempTarget) {
    if (tempTarget === closeBtn || (tempTarget.getAttribute && tempTarget.getAttribute("id") === "detailPanelCloseBtn")) {
      isClickOnCloseBtn = true;
      break;
    }
    tempTarget = tempTarget.parentNode;
  }
  if (isClickOnCloseBtn) {
    closeDetailPanel();
    return;
  }
  if (detailPanel && !detailPanel.contains(target)) {
    closeDetailPanel();
  }
}
function closeDetailPanel() {
  var detailPanel = document.getElementById("detailPanel");
  if (detailPanel) {
    detailPanel.setAttribute("visibility", "hidden");
  }
  var svg = document.querySelector("svg");
  svg.removeEventListener("click", closeDetailPanelOnOutsideClick, true);
  currentDetailPanel = null;
}
